67	   * Call this during cold-start (e.g. Splash screen) to check if the app was
68	   * opened by tapping a Notifee notification from a quit state.
69	   * Stores the pending room ID so Splash can consume it after session restore.
70	   */
71	  public static checkInitialNotification = async () => {
72	    const initialNotification = await notifee.getInitialNotification();
73	    if (initialNotification) {
74	      await this.handleNotificationPress(initialNotification.notification, true);
75	    }
76	  };
77	
78	  /** Get and clear the pending room navigation (used by Splash screen) */
79	  public static consumePendingRoomId = (): string | null => {
80	    const roomId = this.pendingRoomId;
81	    this.pendingRoomId = null;
82	    return roomId;
83	  };
84	
85	  public static setPendingRoomId = (roomId: string) => {
86	    this.pendingRoomId = roomId;
87	  };
88	
89	  private static handleNotificationPress = async (
90	    notification: Notification | undefined,
91	    isInitialNotification: boolean,
92	  ) => {
93	    const roomId = notification?.data?.room_id;
94	
95	    if (!roomId || typeof roomId !== "string") return;
96	
97	    // For initial notification (cold start), store the room_id
98	    // and let the Splash screen handle navigation after session restoration
99	    if (isInitialNotification) {
100	      this.pendingRoomId = roomId;
101	      return;
102	    }
103	
104	    // Refresh the room list before navigating to ensure it's up to date
105	    await MatrixCore.refreshRoomList();
106	    await MatrixCore.getClient().awaitRoomRemoteEcho(roomId);
107	
108	    // For foreground/background events (app already running), navigate directly to room
109	    NavigationContainerRef.navigate("room", { roomId });
110	  };
111	
112	  public static create = (payload: CreatePayload) =>
113	    notifee.displayNotification({
114	      android: {
115	        pressAction: { id: "default" },
116	        channelId: this.channelId,
117	        autoCancel: true,
118	        color: "#292929",
119	      },
120	      title: payload.title,
121	      body: payload.message,
122	      id: payload.id,
123	      data: payload.data,
124	    });
